cd /app && python3 - <<'PY'
import csv, math
read = lambda n: list(csv.DictReader(open('input/'+n)))
press = {r['press_id']: r for r in read('press_profiles.csv')}
sect  = {r['section_id']: r for r in read('section_plan.csv')}
for r in read('kit_pages.csv'):
    p = press[sect[r['section_id']]['press_id']]
    eff = math.floor(float(r['artwork_dpi'])*100.0/float(r['placed_scale_pct']))
    fb  = r['full_bleed_design'].strip().lower() == 'true'
    f = []
    if eff < int(p['min_effective_dpi']): f.append('DPI_TOO_LOW')
    if not fb and float(r['margin_in']) < 0.125: f.append('MARGIN_VIOLATION')
    if fb and float(r['bleed_in']) < 0.125: f.append('BLEED_SHORT')
    if float(r['ink_tac_pct']) > int(p['max_tac_pct']): f.append('INK_OVER_LIMIT')
    if int(r['spot_colors']) > int(p['max_spot_colors']): f.append('SPOT_UNSUPPORTED')
    if r['fonts_embedded'].strip().lower() != 'true': f.append('FONT_NOT_EMBEDDED')
    if int(r['element_count']) < int(r['min_element_required']): f.append('ELEMENT_COUNT_SHORT')
    print(r['page_id'], p['press_id'], 'eff='+str(eff), '|'.join(f) or 'none')
PY
